<?php
namespace App\Services\ThemeBuilder;

use App\Models\Site;
use App\Models\Theme;
use Illuminate\Support\Facades\Schema;
use Illuminate\Support\Facades\Storage;

/**
 * Safely removes auto-generated themes: detach tenants, remove assets, avoid orphans.
 * Only deletes themes that are platform templates and either have
 * source=generator (real AI Theme Generator output) or slug in the known
 * legacy seeder list.
 *
 * Phase 2b fix: this previously also matched source=seeder, which is the
 * source value every canonical commercial theme seed command uses
 * (marketplace:seed, nexus:seed, acool:seed, malltina:seed,
 * SalesSupportThemeSeeder) — meaning a call to deleteAutoGeneratedThemes()
 * would have deleted the entire canonical catalog built by
 * `theme-catalog:rebuild`. Narrowed to source=generator only.
 */
class ThemeCleanupService
{
    /** Slugs from legacy ThemeBuilderSampleThemesSeeder (do not delete manually-created themes). */
    public const LEGACY_AUTO_GENERATED_SLUGS = [
        'personal-website',
        'corporate-business',
        'ecommerce-store',
        'personal-resume-onepage',
        'personal-creative-portfolio',
        'corporate-consulting',
        'corporate-saas-b2b',
        'ecommerce-minimal',
        'ecommerce-boutique',
        'ecommerce-digital',
        'ecommerce-digistore',
    ];

    /**
     * Delete only auto-generated platform templates. Preserve manual themes.
     * 1) Detach sites from these themes. 2) Remove thumbnail assets. 3) Delete themes (revisions cascade).
     */
    public function deleteAutoGeneratedThemes(): array
    {
        $query = Theme::query()->whereNull('site_id');

        if (Schema::hasColumn('themes', 'source')) {
            $query->where(function ($q) {
                $q->where('source', Theme::SOURCE_GENERATOR)
                    ->orWhereIn('slug', self::LEGACY_AUTO_GENERATED_SLUGS);
            });
        } else {
            $query->whereIn('slug', self::LEGACY_AUTO_GENERATED_SLUGS);
        }

        $themes = $query->get();

        $deleted = [];
        $detachedSites = 0;

        foreach ($themes as $theme) {
            $siteIds = Site::where('theme_id', $theme->id)->pluck('id')->toArray();
            if (count($siteIds) > 0) {
                Site::where('theme_id', $theme->id)->update(['theme_id' => null]);
                $detachedSites += count($siteIds);
            }

            $this->removeThemeThumbnail($theme);

            $slug = $theme->slug;
            $theme->delete();
            $deleted[] = $slug;
        }

        return [
            'deleted_slugs' => $deleted,
            'deleted_count' => count($deleted),
            'detached_sites_count' => $detachedSites,
        ];
    }

    protected function removeThemeThumbnail(Theme $theme): void
    {
        $path = $theme->thumbnail;
        if (empty($path)) {
            return;
        }
        $path = str_replace(['storage/', 'public/'], '', $path);
        $uploadDisk = config('filesystems.upload_disk', 'public');
        if (Storage::disk($uploadDisk)->exists($path)) {
            Storage::disk($uploadDisk)->delete($path);
        }
    }

    /** Whether any auto-generated themes exist (for conditional cleanup). */
    public function hasAutoGeneratedThemes(): bool
    {
        $query = Theme::query()->whereNull('site_id');
        if (Schema::hasColumn('themes', 'source')) {
            $query->where(function ($q) {
                $q->where('source', Theme::SOURCE_GENERATOR)
                    ->orWhereIn('slug', self::LEGACY_AUTO_GENERATED_SLUGS);
            });
        } else {
            $query->whereIn('slug', self::LEGACY_AUTO_GENERATED_SLUGS);
        }
        return $query->exists();
    }
}
